{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would, if the General Assembly specifically appropriates funds, require the department to provide each LEA enough additional funding for one full-time licensed professional school counselor position at each high school with at least 600 students in grades 10 through 12.",
      "rationale": "Conveys the appropriation condition, allocating agency, recipients, counselor qualifications, and school enrollment threshold."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "An LEA receiving the funding would have to employ a full-time counselor at each funded school. It could use the money to make an existing part-time counselor full-time.",
      "rationale": "In the context of the previously defined eligible schools and counselors, identifies conversion as an allowed way to fulfill the employment requirement."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "An LEA that already employs one full-time licensed professional school counselor for every 250 student members could instead use the money to cover its existing counselor costs and would not have to add positions beyond that ratio.",
      "rationale": "Conveys the qualifying staffing ratio and permission to replace local spending on the counselors employed to meet it."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "An LEA receiving the funding would have to employ a full-time counselor at each funded school. It could use the money to make an existing part-time counselor full-time. An LEA that already employs one full-time licensed professional school counselor for every 250 student members could instead use the money to cover its existing counselor costs and would not have to add positions beyond that ratio.",
      "rationale": "Covers the employment requirement for funded schools and the exception for LEAs meeting the 1:250 ratio; counselor qualifications are established in the preceding sentence."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The funding would be in addition to funds allocated for TISA.",
      "rationale": "Expressly states that the funding supplements TISA allocations."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The state board, in consultation with the department, could set additional duties for counselors in positions funded by the bill.",
      "rationale": "Conveys the board's discretionary authority, required consultation, funded-position scope, and authority to establish duties beyond existing requirements."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "The state board, in consultation with the department, could set additional duties for counselors in positions funded by the bill. It would have to set how much time those counselors spend on the specified counseling and guidance services and any additional duties. Each counselor would have to spend at least 70% of their time working directly with high school students.",
      "rationale": "Covers mandatory time allocation and the 70% direct-service minimum, but does not identify the preventative and developmental services or the requirement to include one or more of the separately listed counseling and guidance services."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "The bill would, if the General Assembly specifically appropriates funds, require the department to provide each LEA enough additional funding",
      "rationale": "Conveys dependence on a specific legislative appropriation, but does not expressly state that the act itself appropriates no funds or prohibit obligations and expenditures without that appropriation."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law for rulemaking.",
      "rationale": "States the immediate effective date for rulemaking purposes."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "Its other provisions would take effect July 1, 2025, and apply beginning with the 2025–2026 school year.",
      "rationale": "Conveys the effective date for other purposes and ongoing application starting with the specified school year."
    }
  ]
}
